use xiom.io;

enum Response {
  Yes,
  No,
  Maybe(reason: Str),
}

fn count_yes(r: Response) -> Int {
  match r {
    Yes => { return 1; }
    _ => { return 0; }
  }
}

fn needs_followup(r: Response) -> Bool {
  match r {
    Maybe(_) => { return true; }
    _ => { return false; }
  }
}

fn get_reason(r: Response) -> Str {
  match r {
    Maybe(reason) => { return reason; }
    _ => { return "N/A"; }
  }
}

fn main() -> Int {
  let r1 = Response.Yes;
  let r2 = Response.No;
  let r3 = Response.Maybe("Working late");
  let r4 = Response.Yes;
  let r5 = Response.Maybe("Sick");
  let yes_count = count_yes(r1) + count_yes(r2) + count_yes(r3) + count_yes(r4) + count_yes(r5);
  var follow = 0;
  if needs_followup(r1) { follow = follow + 1; }
  if needs_followup(r2) { follow = follow + 1; }
  if needs_followup(r3) { follow = follow + 1; }
  if needs_followup(r4) { follow = follow + 1; }
  if needs_followup(r5) { follow = follow + 1; }
  return yes_count + follow;
}
